 "content": "def transform(grid):
    """Summarize marker counts in regions separated by the divider color 2.

    Each region maps to 1 when it contains more than one marker (the
    non-background, non-divider color), otherwise 0.
    """
    rows = [i for i, row in enumerate(grid) if all(v == 2 for v in row)]
    cols = [j for j in range(len(grid[0])) if all(row[j] == 2 for row in grid)]
    row_ranges = []
    start = 0
    for r in rows + [len(grid)]:
        if start < r:
            row_ranges.append(range(start, r))
        start = r + 1
    col_ranges = []
    start = 0
    for c in cols + [len(grid[0])]:
        if start < c:
            col_ranges.append(range(start, c))
        start = c + 1
    marker = next((v for row in grid for v in row if v != 2 and v != 4), None)
    # For the demonstrated palette the background is 9 and marker is 6;
    # for the test palette the background is 4 and marker is 7.
    if marker is None:
        marker = next((v for row in grid for v in row if v != 2), None)
    return [[int(sum(grid[r][c] == marker for r in rr for c in cr) > 1)
             for cr in col_ranges] for rr in row_ranges]

if __name__ == "__main__":
